<svelte:options runes={true} />
<script lang="ts">
  import { onDestroy } from 'svelte';
  import { Button } from '$lib/components/ui';
  import { domainsStore } from './domains.svelte';
  import { newStudioTrack, type AudioEffect, type MediaAssetRef, type StudioTrack } from '$shared/domains';
  const project = $derived(domainsStore.project!);
  const enabled = $derived(domainsStore.packs.find(p => p.id === project.domain)?.enabled ?? false);
  let selected = $state<MediaAssetRef | null>(null);
  let processed = $state<MediaAssetRef | null>(null);
  let originalUrl = $state(''); let processedUrl = $state(''); let spectrumUrl = $state('');
  let player = $state<HTMLAudioElement>(); let canvas = $state<HTMLCanvasElement>();
  let waveform = $state<{ start: number; duration: number; bins: number; channels: number[][][] } | null>(null);
  let regionStart = $state(0); let regionEnd = $state(5); let lowHz = $state(0); let highHz = $state(12000); let regionOffset = $state(0);
  let attenuation = $state(-12); let playingB = $state(false); let loudnessA = $state<number | null>(null); let loudnessB = $state<number | null>(null);
  let inspection = $state(''); let busy = $state(false); let loop = $state(false);
  let dragStart = $state<{ time: number; hz: number } | null>(null); let paint = $state(false); let spectralPoints = $state<Array<{ time: number; frequency: number; amplitude: number }>>([]);
  let recorder = $state<MediaRecorder | null>(null); let recordingStream: MediaStream | null = null;
  function perform(action: () => Promise<unknown>) { busy = true; void action().catch(error => { domainsStore.error = (error as Error).message; }).finally(() => { busy = false; }); }
  function revoke(url: string) { if (url) URL.revokeObjectURL(url); }
  onDestroy(() => { revoke(originalUrl); revoke(processedUrl); revoke(spectrumUrl); recorder?.stop(); recordingStream?.getTracks().forEach(t => t.stop()); });
  async function choose(asset: MediaAssetRef) {
    selected = asset; processed = null; playingB = false; loudnessA = null; loudnessB = null; revoke(originalUrl); originalUrl = await domainsStore.url(asset); revoke(processedUrl); processedUrl = '';
    await viewRegion();
  }
  async function viewRegion() {
    if (!selected) return;
    const args = { assetId: selected.id, start: regionOffset, duration: 30 };
    waveform = await domainsStore.call('music', 'waveform', args);
    const spectrum = await domainsStore.call<{ asset: MediaAssetRef }>('music', 'spectrogram', args);
    revoke(spectrumUrl); spectrumUrl = await domainsStore.url(spectrum.asset);
    regionStart = regionOffset; regionEnd = regionOffset + Math.min(5, waveform?.duration ?? 5);
  }
  $effect(() => {
    const data = waveform; const node = canvas; if (!node || !data) return;
    node.width = 1200; node.height = 140; const ctx = node.getContext('2d'); if (!ctx) return;
    ctx.clearRect(0, 0, node.width, node.height); ctx.strokeStyle = getComputedStyle(node).color; ctx.lineWidth = 1;
    data.channels.forEach((channel, ch) => { const center = (ch + 0.5) * node.height / data.channels.length; const amplitude = node.height / data.channels.length / 2; ctx.beginPath(); channel.forEach((peak, i) => { const x = i / data.bins * node.width; ctx.moveTo(x, center - peak[1] * amplitude); ctx.lineTo(x, center - peak[0] * amplitude); }); ctx.stroke(); });
  });
  function coordinates(event: PointerEvent) { const bounds = event.currentTarget instanceof HTMLElement ? event.currentTarget.getBoundingClientRect() : null; return bounds ? { time: regionOffset + (event.clientX - bounds.left) / bounds.width * (waveform?.duration || 30), hz: (1 - (event.clientY - bounds.top) / bounds.height) * ((selected?.sampleRate || 48000) / 2) } : { time: 0, hz: 0 }; }
  function beginSelection(event: PointerEvent) { if (!enabled) return; const point = coordinates(event); dragStart = point; if (event.currentTarget instanceof HTMLElement) event.currentTarget.setPointerCapture(event.pointerId); if (paint) spectralPoints = [...spectralPoints, { time: point.time - regionOffset, frequency: point.hz, amplitude: 0.5 }]; }
  function moveSelection(event: PointerEvent) { if (!dragStart) return; const point = coordinates(event); if (paint) { if (spectralPoints.length < 10000) spectralPoints = [...spectralPoints, { time: Math.max(0, point.time - regionOffset), frequency: Math.max(0, point.hz), amplitude: 0.5 }]; } else { regionStart = Math.min(dragStart.time, point.time); regionEnd = Math.max(dragStart.time, point.time); lowHz = Math.max(10, Math.min(dragStart.hz, point.hz)); highHz = Math.max(lowHz + 1, Math.max(dragStart.hz, point.hz)); } }
  async function spectralEdit() { if (!selected) return; processed = await domainsStore.call<MediaAssetRef>('music', 'process', { assetId: selected.id, effects: [{ type: 'spectral', start: regionStart, end: regionEnd, lowHz, highHz, gainDb: attenuation }] }, 'write'); revoke(processedUrl); processedUrl = await domainsStore.url(processed); const a = await domainsStore.call<{ loudness: { input_i: string } }>('music', 'inspect', { assetId: selected.id }); const b = await domainsStore.call<{ loudness: { input_i: string } }>('music', 'inspect', { assetId: processed.id }); loudnessA = Number(a.loudness?.input_i); loudnessB = Number(b.loudness?.input_i); }
  async function compare() { const time = player?.currentTime || 0; const wasPlaying = player && !player.paused; playingB = !playingB; if (!player) return; player.src = playingB ? processedUrl : originalUrl; player.currentTime = time; if (loudnessA !== null && loudnessB !== null && Number.isFinite(loudnessA) && Number.isFinite(loudnessB)) { const quieter = Math.min(loudnessA, loudnessB); player.volume = Math.min(1, Math.pow(10, (quieter - (playingB ? loudnessB : loudnessA)) / 20)); } if (wasPlaying) await player.play(); }
  async function addTrack(kind: StudioTrack['kind']) { await domainsStore.patch({ tracks: [...project.tracks, newStudioTrack(kind === 'bus' ? 'Bus' : kind === 'midi' ? 'Instrument' : 'Audio', kind)] }, 'Add track'); }
  async function changeTrack(id: string, changes: Partial<StudioTrack>) { await domainsStore.patch({ tracks: project.tracks.map(t => t.id === id ? { ...t, ...changes } : t) }, 'Edit track'); }
  async function addClip(track: StudioTrack) { if (!selected) return; const duration = selected.duration || waveform?.duration || 5; await changeTrack(track.id, { clips: [...track.clips, { id: crypto.randomUUID(), assetId: selected.id, start: 0, offset: regionStart, duration: Math.min(duration, Math.max(0.01, regionEnd - regionStart)), gainDb: 0 }] }); }
  async function addNote(track: StudioTrack, pitch: number, beat: number) { await changeTrack(track.id, { notes: [...track.notes, { pitch, start: beat * 60 / project.bpm, duration: 60 / project.bpm, velocity: 0.75 }] }); }
  async function render() { const result = await domainsStore.call<{ asset: MediaAssetRef }>('music', 'render', { projectId: project.id, expectedRevision: project.revision }, 'write'); await domainsStore.refreshProjects(); await choose(result.asset); }
  async function synth() { const asset = await domainsStore.call<MediaAssetRef>('music', 'synthesize', { waveform: 'sine', duration: 3, frequency: 220, endFrequency: 880, seed: 1 }, 'write'); await domainsStore.patch({ assets: [...project.assets, asset] }, 'Create synth sound'); await choose(asset); }
  async function synthPaint() { const result = await domainsStore.call<{ asset: MediaAssetRef }>('music', 'spectral_paint', { duration: Math.min(30, waveform?.duration || 5), points: spectralPoints, seed: 1, iterations: 24 }, 'write'); await domainsStore.patch({ assets: [...project.assets, result.asset] }, 'Create spectral sound'); await choose(result.asset); }
  async function record() {
    if (recorder) { recorder.stop(); recorder = null; return; }
    recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true }); const chunks: Blob[] = []; const current = new MediaRecorder(recordingStream); recorder = current;
    current.ondataavailable = event => { if (event.data.size) chunks.push(event.data); };
    current.onstop = () => { recordingStream?.getTracks().forEach(track => track.stop()); const file = new File(chunks, 'recording.webm', { type: current.mimeType || 'audio/webm' }); perform(async () => { const asset = await domainsStore.importFile(file); if (asset) await choose(asset); }); };
    current.start();
  }
  const rulerSeconds = $derived(Math.max(10, ...project.tracks.flatMap(track => track.clips.map(clip => clip.start + clip.duration).concat(track.notes.map(note => note.start + note.duration)))));
  const pianoPitches = Array.from({ length: 12 }, (_, i) => 71 - i);
</script>
<div class="studio">
  <div class="toolbar"><Button size="sm" variant="ghost" disabled={!enabled || busy} onclick={() => perform(() => domainsStore.history('undo'))}>Undo</Button><Button size="sm" variant="ghost" disabled={!enabled || busy} onclick={() => perform(() => domainsStore.history('redo'))}>Redo</Button><label class="import">Import audio<input type="file" accept="audio/*" disabled={!enabled || busy} onchange={(event) => { const file = event.currentTarget.files?.[0]; if (file) perform(async () => { const asset = await domainsStore.importFile(file); if (asset) await choose(asset); }); }} /></label><Button size="sm" variant="ghost" disabled={!enabled} onclick={() => perform(record)}>{recorder ? 'Finish recording' : 'Record'}</Button><Button size="sm" variant="ghost" disabled={!enabled || busy} onclick={() => perform(synth)}>Synth sound</Button><Button size="sm" disabled={!enabled || busy} onclick={() => perform(render)}>Render mix</Button><label>Tempo<input aria-label="Tempo" type="number" min="20" max="400" value={project.bpm} onchange={(e) => perform(() => domainsStore.patch({ bpm: Number(e.currentTarget.value) }, 'Change tempo'))} /></label></div>
  {#if !enabled}<p class="notice">This domain is disabled. Saved work remains available; enable Music & Sound Design in Settings to edit it.</p>{/if}
  {#if domainsStore.error}<p role="alert" class="notice">{domainsStore.error}</p>{/if}
  <div class="workspace">
    <aside><h3>Media</h3>{#each [...project.assets, ...project.renders] as asset}<button class="asset" class:chosen={asset.id === selected?.id} onclick={() => perform(() => choose(asset))}>{asset.name}<small>{asset.duration ? `${asset.duration.toFixed(1)}s · ` : ''}{(asset.bytes / 1024).toFixed(0)} KB</small></button>{/each}<h3>Markers</h3>{#each project.markers as marker}<button class="asset" onclick={() => { if (player) player.currentTime = marker.time; }}>{marker.time.toFixed(2)}s · {marker.label}</button>{/each}<Button size="sm" variant="ghost" disabled={!enabled} onclick={() => perform(() => domainsStore.patch({ markers: [...project.markers, { id: crypto.randomUUID(), time: player?.currentTime || regionStart, label: `Marker ${project.markers.length + 1}` }] }, 'Add marker'))}>Add marker</Button></aside>
    <main>
      {#if selected}
        <div class="viewer"><h3>{selected.name}</h3><canvas bind:this={canvas} aria-label="Audio waveform"></canvas>
          {#if spectrumUrl}<button type="button" class="spectrum" aria-label="Spectrogram selection and painting" tabindex="0" onpointerdown={beginSelection} onpointermove={moveSelection} onpointerup={() => { dragStart = null; }} onkeydown={(e) => { if (e.key === 'Escape') { spectralPoints = []; dragStart = null; } }}><img src={spectrumUrl} alt="Frequency/time spectrogram" draggable="false" />{#if waveform}<div class="selection" style={`left:${(regionStart - regionOffset) / waveform.duration * 100}%;width:${(regionEnd - regionStart) / waveform.duration * 100}%;top:${(1 - highHz / ((selected.sampleRate || 48000) / 2)) * 100}%;height:${(highHz - lowHz) / ((selected.sampleRate || 48000) / 2) * 100}%`}></div>{/if}{#if paint}<svg class="painting" viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true">{#each spectralPoints as point}<circle cx={point.time / (waveform?.duration || 30) * 1000} cy={(1 - point.frequency / ((selected.sampleRate || 48000) / 2)) * 500} r="3" />{/each}</svg>{/if}</button>{/if}
          <div class="toolbar"><label>Start<input aria-label="Selection start seconds" type="number" min="0" step="0.01" bind:value={regionStart} /></label><label>End<input aria-label="Selection end seconds" type="number" min="0" step="0.01" bind:value={regionEnd} /></label><label>Low Hz<input aria-label="Selection low frequency" type="number" min="10" bind:value={lowHz} /></label><label>High Hz<input aria-label="Selection high frequency" type="number" min="10" bind:value={highHz} /></label><label>Attenuation<input aria-label="Attenuation dB" type="number" max="0" min="-96" bind:value={attenuation} /></label><Button size="sm" disabled={!enabled || busy} onclick={() => perform(spectralEdit)}>Audition correction</Button></div>
          <div class="toolbar"><audio bind:this={player} controls src={originalUrl} ontimeupdate={() => { if (loop && player && player.currentTime >= regionEnd) player.currentTime = regionStart; }}></audio><Button size="sm" variant="ghost" onclick={() => { loop = !loop; }} aria-pressed={loop}>Loop selection</Button><Button size="sm" variant="ghost" disabled={!processedUrl} onclick={() => perform(compare)}>{playingB ? 'B · corrected' : 'A · original'}</Button><Button size="sm" variant="ghost" disabled={!enabled} onclick={() => perform(async () => { inspection = JSON.stringify(await domainsStore.call('music', 'inspect', { assetId: selected!.id }), null, 2); })}>Measure</Button><Button size="sm" variant="ghost" aria-pressed={paint} onclick={() => { paint = !paint; }}>Paint spectrum</Button><Button size="sm" disabled={!enabled || !spectralPoints.length || busy} onclick={() => perform(synthPaint)}>Synthesize painting</Button><label>View from<input aria-label="Waveform region offset" type="number" min="0" bind:value={regionOffset} /></label><Button size="sm" variant="ghost" disabled={!enabled || busy} onclick={() => perform(viewRegion)}>Load region</Button></div>
          {#if inspection}<details><summary>Measurements</summary><pre>{inspection}</pre></details>{/if}
        </div>
      {/if}
      <div class="toolbar"><h3>Timeline & mixer</h3><Button size="sm" variant="ghost" disabled={!enabled} onclick={() => perform(() => addTrack('audio'))}>Audio track</Button><Button size="sm" variant="ghost" disabled={!enabled} onclick={() => perform(() => addTrack('midi'))}>MIDI track</Button><Button size="sm" variant="ghost" disabled={!enabled} onclick={() => perform(() => addTrack('bus'))}>Bus</Button></div>
      <div class="timeline"><div class="ruler">{#each Array.from({ length: 11 }, (_, i) => i) as tick}<span>{(tick * rulerSeconds / 10).toFixed(1)}s</span>{/each}</div>
        {#each project.tracks as track (track.id)}
          <section class="track"><div class="track-controls"><input aria-label="Track name" value={track.name} disabled={!enabled} onchange={(e) => perform(() => changeTrack(track.id, { name: e.currentTarget.value }))} /><button disabled={!enabled} aria-pressed={track.mute} onclick={() => perform(() => changeTrack(track.id, { mute: !track.mute }))}>Mute</button><button disabled={!enabled} aria-pressed={track.solo} onclick={() => perform(() => changeTrack(track.id, { solo: !track.solo }))}>Solo</button><label>Gain<input aria-label={`${track.name} gain`} type="range" min="-60" max="12" step="0.5" value={track.gainDb} disabled={!enabled} onchange={(e) => perform(() => changeTrack(track.id, { gainDb: Number(e.currentTarget.value) }))} /></label><label>Pan<input aria-label={`${track.name} pan`} type="range" min="-1" max="1" step="0.05" value={track.pan} disabled={!enabled} onchange={(e) => perform(() => changeTrack(track.id, { pan: Number(e.currentTarget.value) }))} /></label>{#if track.kind === 'audio'}<button disabled={!selected || !enabled} onclick={() => perform(() => addClip(track))}>Add selection</button>{/if}</div>
            <div class="clips">{#each track.clips as clip}<button class="clip" style={`left:${clip.start / rulerSeconds * 100}%;width:${clip.duration / rulerSeconds * 100}%`} onclick={() => { selected = project.assets.find(a => a.id === clip.assetId) ?? null; }}>{project.assets.find(a => a.id === clip.assetId)?.name ?? 'Missing media'}</button>{/each}{#each track.notes as note}<span class="note" style={`left:${note.start / rulerSeconds * 100}%;width:${note.duration / rulerSeconds * 100}%;top:${(127 - note.pitch) / 127 * 30}%`}>{note.pitch}</span>{/each}</div>
            <details class="track-edit"><summary>Clips, routing, effects & automation</summary>
              {#each track.clips as clip}<div class="toolbar"><span>{project.assets.find(a => a.id === clip.assetId)?.name}</span><label>Position<input aria-label="Clip position" type="number" min="0" step="0.01" value={clip.start} onchange={(e) => perform(() => changeTrack(track.id, { clips: track.clips.map(v => v.id === clip.id ? { ...v, start: Number(e.currentTarget.value) } : v) }))} /></label><label>Length<input aria-label="Clip length" type="number" min="0.01" step="0.01" value={clip.duration} onchange={(e) => perform(() => changeTrack(track.id, { clips: track.clips.map(v => v.id === clip.id ? { ...v, duration: Number(e.currentTarget.value) } : v) }))} /></label><button onclick={() => perform(() => changeTrack(track.id, { clips: track.clips.filter(v => v.id !== clip.id) }))}>Remove</button></div>{/each}
              <div class="toolbar"><label>Output<select aria-label="Output bus" value={track.output || ''} onchange={(e) => perform(() => changeTrack(track.id, { output: e.currentTarget.value || undefined }))}><option value="">Master</option>{#each project.tracks.filter(t => t.kind === 'bus' && t.id !== track.id) as bus}<option value={bus.id}>{bus.name}</option>{/each}</select></label><Button size="sm" variant="ghost" onclick={() => perform(() => changeTrack(track.id, { effects: [...track.effects, { type: 'eq', frequency: 1000, gain: -3, q: 1 }] }))}>Add EQ</Button><Button size="sm" variant="ghost" onclick={() => perform(() => changeTrack(track.id, { effects: [...track.effects, { type: 'compressor', threshold: -18, ratio: 3, attack: 10, release: 100 }] }))}>Add compressor</Button><Button size="sm" variant="ghost" onclick={() => perform(() => changeTrack(track.id, { automation: { ...track.automation, gain: [...track.automation.gain, { time: regionStart, value: track.gainDb }].sort((a,b) => a.time - b.time) } }))}>Gain automation point</Button></div>
              <label>Effect chain JSON<textarea aria-label="Effect chain" rows="3" value={JSON.stringify(track.effects, null, 2)} onchange={(e) => perform(() => changeTrack(track.id, { effects: JSON.parse(e.currentTarget.value) as AudioEffect[] }))}></textarea></label>
            </details>
            {#if track.kind === 'midi'}<details class="piano"><summary>Piano roll · one beat per cell</summary><label>Waveform<select aria-label="Instrument waveform" value={track.instrument?.waveform || 'sine'} onchange={(e) => perform(() => changeTrack(track.id, { instrument: { ...(track.instrument || { attack: 0.01, release: 0.1 }), waveform: e.currentTarget.value as 'sine' | 'triangle' | 'square' | 'saw' } }))}><option>sine</option><option>triangle</option><option>square</option><option>saw</option></select></label>{#each pianoPitches as pitch}<div class="piano-row"><span>{pitch}</span>{#each Array.from({ length: 16 }, (_, i) => i) as beat}<button aria-label={`Add MIDI note ${pitch} at beat ${beat}`} disabled={!enabled} class:filled={track.notes.some(n => n.pitch === pitch && Math.abs(n.start - beat * 60 / project.bpm) < 0.01)} onclick={() => perform(() => addNote(track, pitch, beat))}></button>{/each}</div>{/each}</details>{/if}
          </section>
        {/each}
      </div>
    </main>
  </div>
</div>
<style>
  .studio { display:flex; flex-direction:column; height:100%; min-height:0; padding:0.75rem; gap:0.5rem; }.toolbar { display:flex; align-items:center; flex-wrap:wrap; gap:0.5rem; } h3 { font-size:var(--text-sm); font-weight:600; margin:0.25rem 0; } label,.toolbar span,summary,button { font-size:var(--text-xs); } label { display:flex; align-items:center; gap:0.3rem; } input[type=number] { width:4.5rem; } input,select,textarea { background:var(--background); border:1px solid var(--border-subtle); border-radius:var(--radius-sm); padding:0.3rem; color:var(--foreground); font-size:var(--text-xs); } .import { cursor:pointer; padding:0.4rem; border-radius:var(--radius-sm); background:var(--muted); }.import input { max-width:12rem; }.workspace { display:grid; grid-template-columns:11rem minmax(0,1fr); flex:1; overflow:hidden; } aside { overflow:auto; padding:0.5rem; } main { min-width:0; overflow:auto; padding:0.5rem; } .asset { display:block; width:100%; text-align:left; padding:0.5rem; border-radius:var(--radius-sm); }.asset.chosen { background:var(--muted); } small { display:block; color:var(--muted-foreground); font-size:var(--text-xs); }.notice { font-size:var(--text-sm); color:var(--muted-foreground); }.viewer { display:flex; flex-direction:column; gap:0.5rem; } canvas { width:100%; height:7rem; color:var(--muted-foreground); }.spectrum { display:block; width:100%; position:relative; touch-action:none; overflow:hidden; }.spectrum img { display:block; width:100%; max-height:20rem; object-fit:fill; }.selection { position:absolute; background:color-mix(in srgb,var(--work-accent) 15%,transparent); outline:1px solid color-mix(in srgb,var(--work-accent) 50%,transparent); pointer-events:none; }.painting { position:absolute; inset:0; width:100%; height:100%; fill:var(--foreground); pointer-events:none; } audio { height:2rem; width:min(24rem,100%); } pre { font-size:var(--text-code); max-height:12rem; overflow:auto; }.timeline { min-width:35rem; }.ruler { display:flex; justify-content:space-between; color:var(--muted-foreground); font-size:var(--text-xs); }.track { background:var(--muted); border-radius:var(--radius-md); padding:0.5rem; margin:0.4rem 0; }.track-controls { display:flex; gap:0.5rem; align-items:center; flex-wrap:wrap; }.track-controls input[type=range] { width:5rem; }.track-controls input:not([type=range]) { width:8rem; }.clips { height:3rem; position:relative; margin:0.35rem 0; }.clip,.note { position:absolute; border-radius:var(--radius-sm); background:color-mix(in srgb,var(--foreground) 12%,var(--background)); min-width:1rem; overflow:hidden; padding:0.3rem; top:0.2rem; }.note { background:color-mix(in srgb,var(--work-accent) 25%,var(--background)); font-size:var(--text-xs); }.track-edit { font-size:var(--text-xs); }.track-edit textarea { width:100%; font-family:var(--font-mono); }.piano-row { display:grid; grid-template-columns:2rem repeat(16,1fr); height:1rem; }.piano-row button { background:var(--background); border:1px solid var(--border-subtle); }.piano-row button.filled { background:color-mix(in srgb,var(--work-accent) 40%,var(--background)); }.piano { overflow:auto; margin-top:0.5rem; } @media(max-width:700px) { .workspace { grid-template-columns:1fr; } aside { max-height:8rem; } }
</style>
